import{_ as a,o as i,c as o,a2 as n}from"./chunks/framework.BN2sqjC1.js";const g=JSON.parse('{"title":"ADR-0039 — sync.db: candidati al merge persistenti e quarantena dei path illeggibili","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0039-sync-db-candidati-e-quarantena.md","filePath":"adr/0039-sync-db-candidati-e-quarantena.md"}'),t={name:"adr/0039-sync-db-candidati-e-quarantena.md"};function l(r,e,c,s,d,u){return i(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="adr-0039-—-sync-db-candidati-al-merge-persistenti-e-quarantena-dei-path-illeggibili" tabindex="-1">ADR-0039 — sync.db: candidati al merge persistenti e quarantena dei path illeggibili <a class="header-anchor" href="#adr-0039-—-sync-db-candidati-al-merge-persistenti-e-quarantena-dei-path-illeggibili" aria-label="Permalink to &quot;ADR-0039 — sync.db: candidati al merge persistenti e quarantena dei path illeggibili&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Stato</strong></td><td>accettata</td></tr><tr><td><strong>Recepito in</strong></td><td><code>Specifications.md</code> v1.2 (2026-11-02): §3.4.3, §3.4.4 B, §3.4.5 (Appendice C.4)</td></tr><tr><td><strong>Data</strong></td><td>2026-11-01</td></tr><tr><td><strong>Riferimenti spec</strong></td><td>§3.4 (protocollo di sync), §3.4.3 (stato locale <code>sync.db</code>); D-02 (vault privati), D-04; ADR-0009</td></tr><tr><td><strong>Devia dallo spec?</strong></td><td>sì: §3.4.3 va esteso con le tabelle <code>pending_remote</code> e <code>quarantine</code> e con le regole di questo ADR</td></tr></tbody></table><h2 id="contesto" tabindex="-1">Contesto <a class="header-anchor" href="#contesto" aria-label="Permalink to &quot;Contesto&quot;">​</a></h2><p>L&#39;analisi del 2026-11-01 ha trovato due perdite silenziose nel motore di sync del desktop (<code>apps/desktop/internal/sync</code>). Lo stesso codice gira nel workbench web, compilato in WASM.</p><ol><li><strong>Candidati al merge solo in memoria.</strong> Una modifica remota a un file con modifiche locali veniva parcheggiata in una mappa in memoria, mentre il cursore del changelog veniva salvato subito. Se il merge falliva (errore di rete, app chiusa, file modificato di nuovo durante il merge), il candidato spariva e il cursore era già oltre. Il push successivo andava in conflitto all&#39;infinito, e il file finiva in <code>StateConflict</code> senza nessun record nella vista dei conflitti.</li><li><strong>Path non decifrabili.</strong> In un vault privato un errore di decifratura del path, anche solo perché il vault era stato bloccato a metà ciclo, faceva saltare la modifica con il cursore che avanzava. Durante il bootstrap faceva anche finire nel cestino il file locale corrispondente, come se il server l&#39;avesse cancellato.</li></ol><h2 id="decisione" tabindex="-1">Decisione <a class="header-anchor" href="#decisione" aria-label="Permalink to &quot;Decisione&quot;">​</a></h2><ul><li><strong>Tabella <code>pending_remote(file_id PK, rev, change JSON, created_at)</code></strong> (migrazione <code>0002_pending_remote.sql</code>): <ul><li>i candidati vengono scritti nella <strong>stessa transazione</strong> del cursore della pagina;</li><li>si cancellano solo dopo un merge riuscito, oppure quando sono superati;</li><li>se il file cambia durante il merge, il candidato resta per il ciclo successivo;</li><li>un file con un candidato pendente non viene pushato;</li><li>un commit rifiutato con una revisione corrente più nuova genera un candidato sintetico, così il ciclo successivo fa il merge invece di ritentare alla cieca.</li></ul></li><li><strong>Vault bloccato:</strong> un errore di tipo &quot;bloccato&quot; interrompe il pull <strong>prima</strong> che il cursore avanzi (fase <code>locked</code>). Il blocco manuale aspetta la fine del ciclo in corso.</li><li><strong>Tabella <code>quarantine</code>:</strong> un path che non si decifra per un motivo diverso dal blocco viene messo in quarantena (tabella, <code>LastError</code> della riga, log). Il file locale non si tocca. Nel bootstrap ogni voce dell&#39;albero conta come &quot;nota&quot; prima della decifratura, quindi non viene mai interpretata come una cancellazione del server.</li><li><strong>Transazioni:</strong> <code>sync.db</code> ha ora <code>DB.WithTx</code>. Una pagina di pull, l&#39;adozione nel bootstrap, il merge (copia, conflitto, originale) e il rename dalla UI sono atomici.</li><li><strong>Ordine del merge:</strong> la copia di conflitto si scrive <strong>prima</strong> di sovrascrivere l&#39;originale. I nomi delle copie si troncano su confini di carattere UTF-8, entro i limiti di <code>pathrules</code>.</li></ul><h2 id="alternative-considerate" tabindex="-1">Alternative considerate <a class="header-anchor" href="#alternative-considerate" aria-label="Permalink to &quot;Alternative considerate&quot;">​</a></h2><ul><li><strong>Avanzare il cursore solo dopo il merge:</strong> con le pagine di pull da 500 modifiche, un singolo file in errore avrebbe bloccato tutta la sincronizzazione. Scartata.</li><li><strong>Saltare i path illeggibili, ma senza cestinare:</strong> la perdita resterebbe silenziosa e il file non sarebbe più allineato. Scartata.</li></ul><h2 id="conseguenze" tabindex="-1">Conseguenze <a class="header-anchor" href="#conseguenze" aria-label="Permalink to &quot;Conseguenze&quot;">​</a></h2><ul><li><strong>Stato locale:</strong> <code>sync.db</code> ha due tabelle in più. Unlink e la rimozione di un mount le svuotano.</li><li><strong>Candidati irrisolvibili:</strong> un candidato che non si può risolvere (per esempio un blob sparito) tiene il file fuori dal push e segnala un errore a ogni ciclo, finché una modifica più recente del server non lo sostituisce. Prima il file finiva in conflitto in silenzio.</li><li><strong>Blocco manuale più lento:</strong> può attendere un ciclo lungo, per esempio un download grande.</li><li><strong>Da fare:</strong> la quarantena per ora non si vede nella UI, solo nel log e nello stato della riga. Va mostrata nel pannello sync, in una wave successiva.</li><li><strong>Da fare:</strong> il blocco automatico per inattività non si coordina ancora con il motore. Non può più causare perdite, perché l&#39;errore di blocco ferma il pull prima del cursore, ma va allineato nella wave sulla sicurezza dell&#39;host web (W3).</li></ul>',11)])])}const m=a(t,[["render",l]]);export{g as __pageData,m as default};
